-- 603-0590729 (מתחם סוהו): the full model.
-- Lots: supabase/seed/603-0590729.lots.geojson (fill polygons of the תשריט, pdftocairo -svg, georeferenced by the ITM grid ticks).
-- Envelopes: supabase/seed/603-0590729.envelopes.geojson (קו-בנין #a80000, קו בנין עילי #e64c00/#cc0033).
-- Inline copies below: coordinates rounded to 6 decimals, envelopes simplified to 0.3 m, table 5 trimmed to the fields full_model reads.
-- Rights: supabase/seed/603-0590729.table5.json. Lots 902A/902B/903A/903B are 9021/9022/9031/9032 (full_model takes numbers only).
-- On 18.11.2026 gis.ashdod.muni.il did not answer (from the database and from the sandbox), so plan_builders.full_model
-- (which reads the buildings to demolish from it) could not run. This file runs the same function body as a session copy
-- (pg_temp.full_model_osm: the body of plan_builders.full_model read from the catalog, with the existing buildings from
-- OpenStreetMap instead of the municipal layer). When the GIS answers again, the standard call is:
--   select plan_builders.full_model('603-0590729', <lots>, <table5>, null, <envelopes>);  -- then select plan_builders.build_city_twin();
-- Run the whole file in one session.

-- Existing buildings from OpenStreetMap (Overpass), because gis.ashdod.muni.il did not answer on 18.11.2026.
-- Height: building:levels x 3.3 m when tagged, else 13 m (the same symbolic 4 floors as the municipal layer).
create or replace function pg_temp.osm_buildings(p_area geometry)
returns table(g geometry, h numeric)
language plpgsql
set search_path = public, extensions
as $f$
declare
  v_box box2d := ST_Extent(p_area);
  v_res jsonb;
begin
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT', '90');
  select content::jsonb into v_res from extensions.http_get('https://overpass-api.de/api/interpreter?data=' || extensions.urlencode(
    format('[out:json][timeout:80];way["building"](%s,%s,%s,%s);out tags geom;',
           round(ST_YMin(v_box)::numeric, 6), round(ST_XMin(v_box)::numeric, 6), round(ST_YMax(v_box)::numeric, 6), round(ST_XMax(v_box)::numeric, 6))));
  return query
    select x.g, x.h from (
      select ST_SetSRID(ST_MakeValid(ST_MakePolygon(ST_MakeLine(array(
               select ST_MakePoint((p->>'lon')::float8, (p->>'lat')::float8)
               from jsonb_array_elements(e->'geometry') with ordinality t(p, i) order by i)))), 4326) g,
             coalesce(nullif(regexp_replace(e->'tags'->>'building:levels', '[^0-9.]', '', 'g'), '')::numeric * 3.3, 13)::numeric h
      from jsonb_array_elements(v_res->'elements') e
      where e->>'type' = 'way' and jsonb_array_length(e->'geometry') >= 4
        and e->'geometry'->0 = e->'geometry'->-1
    ) x
    where ST_GeometryType(x.g) in ('ST_Polygon', 'ST_MultiPolygon') and ST_Area(ST_Transform(x.g, 2039)) > 30;
end $f$;

-- The basic model (boundary + context within 300 m), as plan_builders.basic_model builds it, with the OSM context.
with blue as (
  select ST_Union(ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326)) g
  from plan_projects p, jsonb_array_elements(p.geojson->'features') f where p.plan_number = '603-0590729'
), area as (select ST_Transform(ST_Buffer(ST_Transform(g, 2039), 300), 4326) g from blue),
context as (select b.g, b.h from area, pg_temp.osm_buildings(area.g) b where ST_Intersects(b.g, area.g))
insert into plan_models (plan_number, model, source, updated_at)
select p.plan_number, jsonb_build_object(
    'plan_number', p.plan_number,
    'sources', jsonb_build_object(
      'boundary', 'גבול התוכנית: איחוד תאי השטח מתשריט מצב מוצע, מעוגן לרשת ITM',
      'context', 'מבנים קיימים: OpenStreetMap (מפת העירייה לא הייתה זמינה). הגובה לפי מספר הקומות כשהוא מסומן, אחרת סמלי, 4 קומות'),
    'summary', jsonb_build_object('lots', 0, 'units_after', coalesce(p.units_planned, 0)),
    'ui', jsonb_build_object('summary_label', concat_ws(' · ', p.title, to_char(p.units_planned, 'FM9,999') || ' דירות בתוכנית'), 'hint', ''),
    'lots', '[]'::jsonb, 'checks', '[]'::jsonb,
    'massing', jsonb_build_object('type', 'FeatureCollection', 'features', '[]'::jsonb),
    'boundary', jsonb_build_object('type', 'FeatureCollection', 'features', (select jsonb_agg(jsonb_build_object(
        'type', 'Feature', 'properties', '{}'::jsonb, 'geometry', ST_AsGeoJSON(ST_ReducePrecision(d.geom, 0.000001))::jsonb))
        from blue, ST_Dump(blue.g) d)),
    'context', jsonb_build_object('type', 'FeatureCollection', 'features', coalesce((select jsonb_agg(jsonb_build_object(
        'type', 'Feature', 'properties', jsonb_build_object('h', round(h, 1)),
        'geometry', ST_AsGeoJSON(ST_ReducePrecision(ST_SimplifyPreserveTopology(g, 0.000003), 0.000001))::jsonb)) from context), '[]'::jsonb))),
  'basic_model (OSM context)', now()
from plan_projects p where p.plan_number = '603-0590729'
on conflict (plan_number) do update set model = excluded.model, source = excluded.source, updated_at = now();

-- The buildings to demolish are read from the context saved above (same OSM buildings, no second Overpass call).
create or replace function pg_temp.context_buildings(p_area geometry)
returns table(g geometry, h numeric)
language sql
set search_path = public, extensions
as $f$
  select x.g, x.h from (
    select ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326) g, (f->'properties'->>'h')::numeric h
    from plan_models m, jsonb_array_elements(m.model->'context'->'features') f
    where m.plan_number = '603-0590729') x
  where ST_Intersects(x.g, p_area);
$f$;

-- Session copy of plan_builders.full_model (same body, read from the catalog), with the existing buildings from the OSM context.
do $d$
declare v_src text;
begin
  select p.prosrc into v_src from pg_proc p join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'plan_builders' and p.proname = 'full_model';
  if position('plan_builders.city_buildings(' in v_src) = 0 then raise exception 'full_model changed: no city_buildings call'; end if;
  v_src := replace(v_src, 'plan_builders.city_buildings(', 'pg_temp.context_buildings(');
  execute format('create or replace function pg_temp.full_model_osm(p_plan_number text, p_lots jsonb, p_t5 jsonb, '
    'p_source text default null, p_envelopes jsonb default null) returns jsonb language plpgsql '
    'set search_path = public, extensions as %L', v_src);
end $d$;

