-- Lot 901: the existing commercial building and the fuel station stay (סעיף 4.3.2 א, 6.11 א), so they are not demolished.
update plan_models m set model = jsonb_set(m.model, '{demolish,features}', coalesce((
  select jsonb_agg(d) from jsonb_array_elements(m.model->'demolish'->'features') d
  where not exists (select 1 from jsonb_array_elements(m.model->'parcels'->'features') p
                    where (p->'properties'->>'lot') = '901'
                      and ST_Intersects(ST_SetSRID(ST_GeomFromGeoJSON(p->'geometry'), 4326),
                                        ST_PointOnSurface(ST_SetSRID(ST_GeomFromGeoJSON(d->'geometry'), 4326))))), '[]'::jsonb))
where m.plan_number = '603-0590729';

update plan_models set model = jsonb_set(model, '{ui,hint}', to_jsonb('המגרשים וקווי הבניין מהתשריט, הקומות והגובה מטבלה 5. הבניין עצמו הוא הערכה. תאי השטח 902A, 902B, 903A ו-903B מסומנים במודל 9021, 9022, 9031 ו-9032. בניין המסחר ותחנת הדלק בתא שטח 901 קיימים ונשארים.'::text))
where plan_number = '603-0590729';
